from rest_framework import serializers
from .models import Review, ReviewHelpful


class ReviewSerializer(serializers.ModelSerializer):
    user = serializers.StringRelatedField(read_only=True)
    user_id = serializers.UUIDField(source="user.id", read_only=True)

    class Meta:
        model = Review
        fields = [
            "id", "user", "user_id", "book",
            "rating", "title", "comment",
            "helpful_count", "is_approved",
            "created_at", "updated_at",
        ]
        read_only_fields = [
            "id", "user", "helpful_count", "is_approved",
            "created_at", "updated_at",
        ]

    def validate_rating(self, value):
        if not 1 <= value <= 5:
            raise serializers.ValidationError("امتیاز باید بین ۱ تا ۵ باشد.")
        return value

    def validate(self, attrs):
        user = self.context["request"].user
        book = attrs.get("book")
        if self.instance is None and book and Review.objects.filter(user=user, book=book).exists():
            raise serializers.ValidationError("شما قبلاً برای این کتاب نظر داده‌اید.")
        return attrs


class ReviewApprovalSerializer(serializers.ModelSerializer):
    class Meta:
        model = Review
        fields = ["is_approved"]

from rest_framework import viewsets, mixins
from rest_framework.decorators import action
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response

from common.permissions import IsOwnerOrReadOnly
from .models import Loan, Reservation
from .serializers import LoanSerializer, ReservationSerializer
from .services import create_loan, return_loan, extend_loan, create_reservation


class LoanViewSet(
    mixins.ListModelMixin,
    mixins.RetrieveModelMixin,
    mixins.CreateModelMixin,
    viewsets.GenericViewSet,
):
    serializer_class = LoanSerializer
    permission_classes = [IsAuthenticated, IsOwnerOrReadOnly]

    def get_queryset(self):
        return (
            Loan.objects.filter(user=self.request.user)
            .select_related("book", "book__author")
        )

    def perform_create(self, serializer):
        from catalog.models import Book
        book_id = self.request.data.get("book")
        book = Book.objects.get(pk=book_id)
        loan = create_loan(user=self.request.user, book=book)
        serializer.instance = loan

    @action(detail=True, methods=["post"])
    def return_book(self, request, pk=None):
        loan = self.get_object()
        loan = return_loan(loan=loan)
        return Response(LoanSerializer(loan).data)

    @action(detail=True, methods=["post"])
    def extend(self, request, pk=None):
        loan = self.get_object()
        loan = extend_loan(loan=loan)
        return Response(LoanSerializer(loan).data)


class ReservationViewSet(
    mixins.ListModelMixin,
    mixins.RetrieveModelMixin,
    mixins.CreateModelMixin,
    mixins.DestroyModelMixin,
    viewsets.GenericViewSet,
):
    serializer_class = ReservationSerializer
    permission_classes = [IsAuthenticated, IsOwnerOrReadOnly]

    def get_queryset(self):
        return Reservation.objects.filter(user=self.request.user).select_related("book")

    def perform_create(self, serializer):
        from catalog.models import Book
        book_id = self.request.data.get("book")
        book = Book.objects.get(pk=book_id)
        res = create_reservation(user=self.request.user, book=book)
        serializer.instance = res

    def perform_destroy(self, instance):
        if instance.status not in ("waiting",):
            from common.exceptions import BusinessRuleViolation
            raise BusinessRuleViolation("فقط رزروهای در انتظار قابل لغو هستند.")
        instance.status = "cancelled"
        instance.save(update_fields=["status"])

