from .models import Subscription, Payment
from .serializers import SubscriptionSerializer, PaymentSerializer, PaymentInitSerializer
from .services import initiate_payment, verify_payment


class SubscriptionViewSet(mixins.ListModelMixin, mixins.RetrieveModelMixin, viewsets.GenericViewSet):
    serializer_class = SubscriptionSerializer
    permission_classes = [IsAuthenticated]

    def get_queryset(self):
        return Subscription.objects.filter(user=self.request.user)


class PaymentViewSet(mixins.ListModelMixin, mixins.RetrieveModelMixin, viewsets.GenericViewSet):
    serializer_class = PaymentSerializer
    permission_classes = [IsAuthenticated]

    def get_queryset(self):
        return Payment.objects.filter(user=self.request.user)

    @action(detail=False, methods=["post"])
    def initiate(self, request):
        serializer = PaymentInitSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        payment, payment_url = initiate_payment(
            user=request.user,
            tier=serializer.validated_data["tier"],
            gateway=serializer.validated_data["gateway"],
        )
        return Response({
            "payment": PaymentSerializer(payment).data,
            "payment_url": payment_url,
        }, status=status.HTTP_201_CREATED)

    @action(detail=True, methods=["post"], permission_classes=[])
    def verify(self, request, pk=None):
        """Callback از درگاه پرداخت."""
        from django.shortcuts import get_object_or_404
        payment = get_object_or_404(Payment, pk=pk)
        payment = verify_payment(payment=payment, gateway_response=request.data)
        return Response(PaymentSerializer(payment).data)

import logging
from django.utils import timezone
from .models import Notification

logger = logging.getLogger("api.notifications")


def send_notification(*, user, type, title, message, payload=None, priority="normal"):
    """ساخت اعلان و ارسال ایمیل/پوش در پس‌زمینه."""
    notification = Notification.objects.create(
        user=user,
        type=type,
        title=title,
        message=message,
        payload=payload or {},
        priority=priority,
    )

    # ارسال ایمیل اگر کاربر فعال کرده باشد
    profile = getattr(user, "profile", None)
    if profile and profile.notification_email:
        try:
            from .tasks import send_notification_email
            send_notification_email.delay(str(notification.id))
        except Exception as e:
            logger.warning(f"Failed to queue notification email: {e}")

    return notification


def mark_as_read(*, notification):
    if not notification.is_read:
        notification.is_read = True
        notification.read_at = timezone.now()
        notification.save(update_fields=["is_read", "read_at"])
    return notification


def mark_all_as_read(*, user):
    return Notification.objects.filter(user=user, is_read=False).update(
        is_read=True, read_at=timezone.now()
    )

from rest_framework import viewsets, mixins
from rest_framework.decorators import action
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from .models import Notification
from .serializers import NotificationSerializer
from .services import mark_as_read, mark_all_as_read


class NotificationViewSet(
    mixins.ListModelMixin,
    mixins.RetrieveModelMixin,
    viewsets.GenericViewSet,
):
    serializer_class = NotificationSerializer
    permission_classes = [IsAuthenticated]

    def get_queryset(self):
        qs = Notification.objects.filter(user=self.request.user)
        is_read = self.request.query_params.get("is_read")
        if is_read is not None:
            qs = qs.filter(is_read=is_read.lower() == "true")
        return qs

    @action(detail=True, methods=["post"])
    def mark_read(self, request, pk=None):
        notification = self.get_object()
        mark_as_read(notification=notification)
        return Response(NotificationSerializer(notification).data)

    @action(detail=False, methods=["post"])
    def mark_all_read(self, request):
        count = mark_all_as_read(user=request.user)
        return Response({"marked": count})

    @action(detail=False, methods=["get"])
    def unread_count(self, request):
        count = Notification.objects.filter(user=request.user, is_read=False).count()
        return Response({"count": count})

from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated, IsAdminUser
from rest_framework.response import Response
from django.db.models import Count, Sum, Avg, Q
from django.utils import timezone
from datetime import timedelta


@api_view(["GET"])
@permission_classes([IsAuthenticated])
def dashboard(request):
    """داشبورد کاربر."""
    from loans.models import Loan
    from reviews.models import Review
    from favorites.models import Favorite
    from notifications.models import Notification

    user = request.user
    return Response({
        "active_loans": Loan.objects.filter(user=user, status="active").count(),
        "overdue_loans": Loan.objects.filter(user=user, status="overdue").count(),
        "total_loans": Loan.objects.filter(user=user).count(),
        "my_reviews": Review.objects.filter(user=user).count(),
        "my_favorites": Favorite.objects.filter(user=user).count(),
        "unread_notifications": Notification.objects.filter(user=user, is_read=False).count(),
    })


@api_view(["GET"])
@permission_classes([IsAdminUser])
def admin_stats(request):
    """آمار کلی سیستم."""
    from catalog.models import Book
    from loans.models import Loan
    from payments.models import Payment
    from django.contrib.auth import get_user_model

    User = get_user_model()
    last_30d = timezone.now() - timedelta(days=30)

    return Response({
        "users": {
            "total": User.objects.count(),
            "new_30d": User.objects.filter(date_joined__gte=last_30d).count(),
            "verified": User.objects.filter(is_email_verified=True).count(),
        },
        "books": {
            "total": Book.objects.filter(is_deleted=False).count(),
            "published": Book.objects.filter(is_published=True, is_deleted=False).count(),
            "featured": Book.objects.filter(is_featured=True, is_deleted=False).count(),
        },
        "loans": {
            "total": Loan.objects.count(),
            "active": Loan.objects.filter(status="active").count(),
            "overdue": Loan.objects.filter(status="overdue").count(),
            "last_30d": Loan.objects.filter(created_at__gte=last_30d).count(),
        },
        "revenue": {
            "total": Payment.objects.filter(status="success").aggregate(Sum("amount"))["amount__sum"] or 0,
            "last_30d": Payment.objects.filter(status="success", paid_at__gte=last_30d).aggregate(Sum("amount"))["amount__sum"] or 0,
            "count_30d": Payment.objects.filter(status="success", paid_at__gte=last_30d).count(),
        },
    })


@api_view(["GET"])
@permission_classes([IsAdminUser])
def top_books(request):
    """کتاب‌های برتر."""
    from catalog.models import Book
    from django.db.models import Avg, Count

    top_by_loans = list(
        Book.objects.filter(is_published=True, is_deleted=False)
        .order_by("-loans_count")
        .values("id", "title", "loans_count", "views_count")[:10]
    )
    top_by_rating = list(
        Book.objects.filter(is_published=True, is_deleted=False)
        .annotate(avg_rating=Avg("reviews__rating", filter=Q(reviews__is_approved=True)))
        .filter(avg_rating__gte=4)
        .order_by("-avg_rating")[:10]
        .values("id", "title", "avg_rating")
    )
    return Response({
        "top_by_loans": top_by_loans,
        "top_by_rating": top_by_rating,
    })
